begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('cccccccc-cccc-4ccc-8ccc-cccccccccccc','duplicate-fixture@example.test',now());
insert into public.profiles(id,display_name) values('cccccccc-cccc-4ccc-8ccc-cccccccccccc','Duplicate fixture');
select public.record_health_consent('cccccccc-cccc-4ccc-8ccc-cccccccccccc','2026-11-12-v1');
insert into public.health_connections(id,user_id,provider,status) values('dddddddd-dddd-4ddd-8ddd-dddddddddddd','cccccccc-cccc-4ccc-8ccc-cccccccccccc','google_health','connected');
set local role authenticated;
select set_config('request.jwt.claim.sub','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true);
select throws_ok($$select public.reconcile_health_deletions('dddddddd-dddd-4ddd-8ddd-dddddddddddd',now())$$,'42501','permission denied for function reconcile_health_deletions','browser cannot delete provider history through privileged reconciliation');
reset role;
set local role service_role;
select public.upsert_health_activity('{"user_id":"cccccccc-cccc-4ccc-8ccc-cccccccccccc","provider":"google_health","provider_workout_id":"source-a","type":"running","started_at":"2026-11-01T10:00:00Z","ended_at":"2026-11-01T10:30:00Z","provenance":{"origin_provider":"watch","origin_workout_id":"origin-a"}}');
select public.upsert_health_activity('{"user_id":"cccccccc-cccc-4ccc-8ccc-cccccccccccc","provider":"google_health","provider_workout_id":"source-b","type":"running","started_at":"2026-11-01T10:00:00Z","ended_at":"2026-11-01T10:30:00Z","provenance":{"origin_provider":"watch","origin_workout_id":"origin-a"}}');
select public.upsert_health_activity('{"user_id":"cccccccc-cccc-4ccc-8ccc-cccccccccccc","provider":"google_health","provider_workout_id":"source-c","type":"running","started_at":"2026-11-01T10:00:00Z","ended_at":"2026-11-01T10:30:00Z","provenance":{"origin_provider":"watch","origin_workout_id":"origin-a"}}');
select is((select count(*) from public.activities),3::bigint,'all three source records retained');
select is((select count(*) from public.activities where duplicate_of is null),1::bigint,'one canonical workout for three matching origins');
delete from public.activities where duplicate_of is null;
select is((select count(*) from public.activities),2::bigint,'canonical source deletion retains both surviving sources');
select is((select count(*) from public.activities where duplicate_of is null),1::bigint,'deleting canonical promotes exactly one surviving source');
select is((select count(*) from public.activities a join public.activities canonical on a.duplicate_of=canonical.id where canonical.duplicate_of is null),1::bigint,'other surviving duplicate is reparented to new canonical');
-- Provider corrections that split origin identities must not keep distinct runs hidden.
update public.activities set provenance='{"origin_provider":"watch","origin_workout_id":"origin-b"}' where duplicate_of is null;
select is((select count(*) from public.activities where duplicate_of is null),2::bigint,'origin correction splits now-distinct workouts');
update public.activities set provenance='{"origin_provider":"watch","origin_workout_id":"origin-a"}';
select is((select count(*) from public.activities where duplicate_of is null),1::bigint,'origin correction can merge proven duplicates again');
update public.activities set provenance='{}' where duplicate_of is not null;
select is((select count(*) from public.activities where duplicate_of is null),2::bigint,'absent origin evidence cannot keep a workout hidden as duplicate');
select is(public.reconcile_health_deletions('dddddddd-dddd-4ddd-8ddd-dddddddddddd',now()+interval '1 second'),2,'successful full reconciliation deletes missing source records');
select is((select count(*) from public.activities),0::bigint,'no stale provider workouts remain after full reconciliation');
update public.health_connections set status='disconnected' where id='dddddddd-dddd-4ddd-8ddd-dddddddddddd';
select throws_ok($$select public.reconcile_health_deletions('dddddddd-dddd-4ddd-8ddd-dddddddddddd',now())$$,'42501','Health connection is not active','stale disconnected sync cannot reconcile or restore access');
reset role;
select * from finish();
rollback;
